  /** Non-fatal errors encountered while scanning. */
  discoveryErrors: string[];
}

const SETTINGS_FILE = 'settings.json';
const COMMANDS_DIR = 'commands';
const SKILLS_DIR = 'skills';
const SKILL_FILE = 'SKILL.md';

const MCP_SERVERS_KEY = 'mcpServers';
const HOOKS_KEY = 'hooks';

/**
 * Scans a workspace's `.gemini` configuration directory and summarizes its
 * contents so that a user can make an informed decision before trusting the
 * folder.
 */
export class FolderTrustDiscoveryService {
  /**
   * Scans the given workspace directory for Gemini configuration.
   *
   * @param workspaceDir Absolute path to the workspace/project directory.
   * @returns A summary of the discovered configuration. All arrays are empty
   *   and no errors are reported when the `.gemini` directory is absent.
   */
  static async discover(
    workspaceDir: string,
  ): Promise<FolderDiscoveryResults> {
    const results: FolderDiscoveryResults = {
      commands: [],
      mcps: [],
      hooks: [],
      skills: [],
      settings: [],
      securityWarnings: [],
      discoveryErrors: [],
    };

    const geminiDir = path.join(workspaceDir, GEMINI_DIR);

    // If the configuration directory does not exist there is nothing to
    // discover and, importantly, nothing to warn about.
    if (!(await isDirectory(geminiDir))) {
      return results;
    }

    await Promise.all([
      discoverCommands(geminiDir, results),
      discoverSkills(geminiDir, results),
      discoverSettings(geminiDir, results),
    ]);

    addSecurityWarnings(results);

    return results;
  }
}

/** Returns true if the given path exists and is a directory. */
async function isDirectory(dirPath: string): Promise<boolean> {
  try {
    const stat = await fs.stat(dirPath);
    return stat.isDirectory();
  } catch {
    return false;
  }
}

async function discoverCommands(
  geminiDir: string,
  results: FolderDiscoveryResults,
): Promise<void> {
  const commandsDir = path.join(geminiDir, COMMANDS_DIR);
  if (!(await isDirectory(commandsDir))) {
    return;
  }

  try {
    const commands = new Set<string>();
    await walkForToml(commandsDir, commands);
    results.commands = Array.from(commands).sort();
  } catch (error) {
    results.discoveryErrors.push(
      `Failed to discover commands: ${errorMessage(error)}`,
    );
  }
}

/** Recursively collects TOML command names (file name without extension). */
async function walkForToml(dir: string, out: Set<string>): Promise<void> {
  const entries = await fs.readdir(dir, { withFileTypes: true });
  for (const entry of entries) {
    const entryPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      await walkForToml(entryPath, out);
    } else if (entry.isFile() && entry.name.endsWith('.toml')) {
      out.add(path.basename(entry.name, '.toml'));
    }
  }
}

async function discoverSkills(
  geminiDir: string,
  results: FolderDiscoveryResults,
): Promise<void> {
  const skillsDir = path.join(geminiDir, SKILLS_DIR);
  if (!(await isDirectory(skillsDir))) {
    return;
  }

  try {
    const entries = await fs.readdir(skillsDir, { withFileTypes: true });
    const skills: string[] = [];
    for (const entry of entries) {
      if (!entry.isDirectory()) {
        continue;
      }
      const skillFile = path.join(skillsDir, entry.name, SKILL_FILE);
      if (await isFile(skillFile)) {
        skills.push(entry.name);
      }
    }
    results.skills = skills.sort();
  } catch (error) {
    results.discoveryErrors.push(
      `Failed to discover skills: ${errorMessage(error)}`,
    );
  }
}

/** Returns true if the given path exists and is a regular file. */
async function isFile(filePath: string): Promise<boolean> {
  try {
    const stat = await fs.stat(filePath);
    return stat.isFile();
  } catch {
    return false;
  }
}

async function discoverSettings(
  geminiDir: string,
  results: FolderDiscoveryResults,
): Promise<void> {
  const settingsPath = path.join(geminiDir, SETTINGS_FILE);

  let raw: string;
  try {
    raw = await fs.readFile(settingsPath, 'utf-8');
  } catch {
    // No settings file is a perfectly valid state.
    return;
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (error) {
    results.discoveryErrors.push(
      `Failed to discover settings: ${errorMessage(error)}`,
    );
    return;
  }

  // A settings file that is not a JSON object (array, string, number, null,
  // etc.) has no top-level keys to display. This is not treated as an error.
  if (!isPlainObject(parsed)) {
    return;
  }

  const mcpServers = parsed[MCP_SERVERS_KEY];
  if (isPlainObject(mcpServers)) {
    results.mcps = Object.keys(mcpServers);
  }

  results.hooks = extractHookCommands(parsed[HOOKS_KEY]);

  results.settings = Object.keys(parsed).filter(
    (key) => key !== MCP_SERVERS_KEY && key !== HOOKS_KEY,
  );
}

/**
 * Recursively collects the value of every `command` string property found
 * within the hooks configuration, regardless of nesting.
 */
function extractHookCommands(hooks: unknown): string[] {
  const commands: string[] = [];

  const collect = (node: unknown): void => {
    if (Array.isArray(node)) {
      for (const item of node) {
        collect(item);
      }
    } else if (node && typeof node === 'object') {
      for (const [key, value] of Object.entries(node)) {
        if (key === 'command' && typeof value === 'string') {
          commands.push(value);
        } else {
          collect(value);
        }
      }
    }
  };

  collect(hooks);
  return commands;
}

/**
 * Adds warnings for configuration that can execute code or otherwise expand
 * Gemini's capabilities in the folder.
 */
function addSecurityWarnings(results: FolderDiscoveryResults): void {
  if (results.mcps.length > 0) {
    results.securityWarnings.push(
      'This folder configures MCP servers that can execute external tools and code.',
    );
  }

  if (results.hooks.length > 0) {
    results.securityWarnings.push(
      'This folder configures hooks that run shell commands automatically.',
    );
  }

  if (results.commands.length > 0) {
    results.securityWarnings.push(
      'This folder defines custom commands that can run shell commands.',
    );
  }
}

/** Type guard for a non-null, non-array plain object. */
function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

